from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence, Tuple

import torch
import torch.nn as nn
import torch.nn.functional as F

from cinlm.attention import HybridAttention, RMSNorm, precompute_rope_cache
from cinlm.config import CinLMConfig
from cinlm.engram import EngramMemory, EngramState
from cinlm.moe import ReLU2MLP, SparseReLU2MoE


@dataclass
class InterventionSpec:
    """Declarative causal intervention spec — easily generated by a Frontier LLM
    and executed verbatim on CinLM to verify mechanistic hypotheses.
    """

    # Map layer_idx -> list of attention head indices to zero out
    ablate_attn_heads: Dict[int, List[int]] = field(default_factory=dict)
    # Map layer_idx -> fixed Engram gate value (e.g., 0.0 to ablate Engram, 1.0 to clamp open)
    force_engram_gate: Dict[int, float] = field(default_factory=dict)
    # Map layer_idx -> list of routed expert indices to zero out
    ablate_experts: Dict[int, List[int]] = field(default_factory=dict)
    # Set of layer_idx where the shared expert is zeroed out
    ablate_shared_layers: List[int] = field(default_factory=list)


@dataclass
class CinLMCache:
    """Exact incremental state across all layers (Hybrid KV cache + Engram causal state)."""

    kv_caches: List[Optional[Tuple[torch.Tensor, torch.Tensor]]]
    engram_states: Dict[int, EngramState]
    seq_len: int = 0


class CinLMBlock(nn.Module):
    """Single additive residual block for CinLM.

    Residual stream decomposition (kept strictly linear/additive for Logit Lens & DLA):
        x <- x + Engram(x, input_ids)          [only on engram_layers]
        x <- x + HybridAttention(RMSNorm(x))
        x <- x + SparseReLU2MoE(RMSNorm(x))    [or Dense ReLU2MLP]
    """

    def __init__(self, config: CinLMConfig, layer_idx: int) -> None:
        super().__init__()
        self.layer_idx = layer_idx
        self.engram = EngramMemory(config, layer_idx) if config.is_engram_layer(layer_idx) else None
        self.attn_norm = RMSNorm(config.d_model, eps=config.rms_norm_eps)
        self.attn = HybridAttention(config, layer_idx)
        self.ffn_norm = RMSNorm(config.d_model, eps=config.rms_norm_eps)
        self.use_moe = config.use_moe
        if config.use_moe:
            self.ffn: nn.Module = SparseReLU2MoE(config, layer_idx)
        else:
            self.ffn = ReLU2MLP(config.d_model, config.d_ff_dense)

    def forward(
        self,
        x: torch.Tensor,
        input_ids: torch.Tensor,
        rope_cos: torch.Tensor,
        rope_sin: torch.Tensor,
        start_pos: int = 0,
        kv_cache: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
        engram_state: Optional[EngramState] = None,
        intervention: Optional[InterventionSpec] = None,
        capture_telemetry: bool = False,
        skip_engram: bool = False,
    ) -> Tuple[
        torch.Tensor,
        Tuple[torch.Tensor, torch.Tensor],
        Optional[EngramState],
        Optional[Dict[str, Any]],
    ]:
        layer_tel: Optional[Dict[str, Any]] = {} if capture_telemetry else None

        # 1. Optional Engram conditional memory (skipped on recursive loop passes r >= 1)
        new_engram_state: Optional[EngramState] = engram_state
        if self.engram is not None and not skip_engram:
            force_gate = (
                intervention.force_engram_gate.get(self.layer_idx)
                if intervention is not None
                else None
            )
            engram_out, new_engram_state, eng_tel = self.engram(
                x,
                input_ids,
                state=engram_state,
                force_gate=force_gate,
                return_telemetry=capture_telemetry,
            )
            x = x + engram_out
            if capture_telemetry and layer_tel is not None:
                layer_tel["engram_delta"] = engram_out.detach()
                layer_tel["engram_telemetry"] = eng_tel

        # 2. Hybrid Attention (SWA or Global)
        ablate_heads = (
            intervention.ablate_attn_heads.get(self.layer_idx)
            if intervention is not None
            else None
        )
        attn_out, new_kv, attn_weights = self.attn(
            self.attn_norm(x),
            rope_cos=rope_cos,
            rope_sin=rope_sin,
            start_pos=start_pos,
            kv_cache=kv_cache,
            return_attn_weights=capture_telemetry,
            ablate_heads=ablate_heads,
        )
        x = x + attn_out
        if capture_telemetry and layer_tel is not None:
            layer_tel["attn_delta"] = attn_out.detach()
            layer_tel["attn_is_global"] = self.attn.is_global
            layer_tel["attn_weights"] = attn_weights

        # 3. Feed-Forward (Sparse ReLU² MoE or Dense ReLU² MLP)
        if self.use_moe:
            ablate_experts = (
                intervention.ablate_experts.get(self.layer_idx)
                if intervention is not None
                else None
            )
            ablate_shared = (
                self.layer_idx in intervention.ablate_shared_layers
                if intervention is not None
                else False
            )
            ffn_out, moe_tel = self.ffn(
                self.ffn_norm(x),
                ablate_experts=ablate_experts,
                ablate_shared=ablate_shared,
                return_telemetry=capture_telemetry,
            )
            if capture_telemetry and layer_tel is not None:
                layer_tel["ffn_delta"] = ffn_out.detach()
                layer_tel["moe_telemetry"] = moe_tel
        else:
            ffn_out, mlp_stats = self.ffn(self.ffn_norm(x), return_stats=capture_telemetry)
            if capture_telemetry and layer_tel is not None:
                layer_tel["ffn_delta"] = ffn_out.detach()
                layer_tel["mlp_stats"] = mlp_stats

        x = x + ffn_out
        if capture_telemetry and layer_tel is not None:
            layer_tel["residual_post"] = x.detach()

        return x, new_kv, new_engram_state, layer_tel


class CinLM(nn.Module):
    """CinLM: PT-BR Small Language Model with Hybrid Attention + Engram + Sparse ReLU² MoE,
    engineered for Frontier-LLM mechanistic interpretability.
    """

    def __init__(self, config: CinLMConfig) -> None:
        super().__init__()
        self.config = config
        self.gradient_checkpointing = False
        self.tok_emb = nn.Embedding(config.vocab_size, config.d_model)
        self.layers = nn.ModuleList([CinLMBlock(config, i) for i in range(config.n_layers)])
        self.final_norm = RMSNorm(config.d_model, eps=config.rms_norm_eps)
        self.lm_head = nn.Linear(config.d_model, config.vocab_size, bias=False)

        if config.tie_word_embeddings:
            self.lm_head.weight = self.tok_emb.weight

        # Optional Looped Core parameters (function-preserving zero init at step 0)
        if config.loop_core_steps > 1:
            self.loop_step_emb: Optional[nn.Embedding] = nn.Embedding(config.loop_max_steps, config.d_model)
            self.loop_res_scale: Optional[nn.Parameter] = nn.Parameter(torch.zeros(config.loop_max_steps))
        else:
            self.loop_step_emb = None
            self.loop_res_scale = None

        # Optional Multi-Token Prediction (MTP) auxiliary heads (training-only, zero inference overhead)
        if config.mtp_num_heads > 0:
            self.mtp_norms: Optional[nn.ModuleList] = nn.ModuleList(
                [RMSNorm(config.d_model, eps=config.rms_norm_eps) for _ in range(config.mtp_num_heads)]
            )
            self.mtp_emb_norms: Optional[nn.ModuleList] = nn.ModuleList(
                [RMSNorm(config.d_model, eps=config.rms_norm_eps) for _ in range(config.mtp_num_heads)]
            )
            self.mtp_projs: Optional[nn.ModuleList] = nn.ModuleList(
                [nn.Linear(2 * config.d_model, config.d_model, bias=False) for _ in range(config.mtp_num_heads)]
            )
            self.mtp_out_norms: Optional[nn.ModuleList] = nn.ModuleList(
                [RMSNorm(config.d_model, eps=config.rms_norm_eps) for _ in range(config.mtp_num_heads)]
            )
        else:
            self.mtp_norms = None
            self.mtp_emb_norms = None
            self.mtp_projs = None
            self.mtp_out_norms = None

        cos, sin = precompute_rope_cache(config.max_seq_len, config.head_dim, config.rope_theta)
        self.register_buffer("rope_cos", cos, persistent=False)
        self.register_buffer("rope_sin", sin, persistent=False)

        self.apply(self._init_weights)
        # Re-zero Engram conv weights and Looped Core adapters after global init
        for layer in self.layers:
            if layer.engram is not None:
                nn.init.zeros_(layer.engram.conv.weight)
        if self.loop_step_emb is not None:
            nn.init.zeros_(self.loop_step_emb.weight)
        if self.loop_res_scale is not None:
            nn.init.zeros_(self.loop_res_scale)

    def _init_weights(self, module: nn.Module) -> None:
        if isinstance(module, nn.Linear):
            nn.init.normal_(module.weight, mean=0.0, std=self.config.init_std)
            if module.bias is not None:
                nn.init.zeros_(module.bias)
        elif isinstance(module, nn.Embedding):
            nn.init.normal_(module.weight, mean=0.0, std=self.config.init_std)

    def update_moe_router_biases(self) -> None:
        """Call once per optimizer step for auxiliary-loss-free MoE load balancing."""
        for layer in self.layers:
            if isinstance(layer.ffn, SparseReLU2MoE):
                layer.ffn.update_router_bias()

    def count_parameters(self) -> Dict[str, int]:
        """Exact runtime parameter count (deduplicating tied weights)."""
        seen = set()
        total = 0
        for p in self.parameters():
            if id(p) not in seen:
                seen.add(id(p))
                total += p.numel()
        est = self.config.estimate_parameters()
        return {
            "exact_total": total,
            "estimated_total": est["total"],
            "estimated_active_per_token": est["active_per_token"],
        }

    def forward(
        self,
        input_ids: torch.Tensor,
        labels: Optional[torch.Tensor] = None,
        cache: Optional[CinLMCache] = None,
        use_cache: bool = False,
        intervention: Optional[InterventionSpec] = None,
        capture_telemetry: bool = False,
        num_loops: Optional[int] = None,
    ) -> Dict[str, Any]:
        bsz, seq_len = input_ids.shape
        start_pos = cache.seq_len if cache is not None else 0
        assert start_pos + seq_len <= self.config.max_seq_len, (
            f"Sequence length {start_pos + seq_len} exceeds max_seq_len {self.config.max_seq_len}"
        )

        active_loops = self.config.loop_core_steps if num_loops is None else int(num_loops)
        assert 1 <= active_loops <= self.config.loop_max_steps, (
            f"num_loops={active_loops} must be in [1, {self.config.loop_max_steps}]"
        )
        if active_loops > 1:
            assert self.loop_step_emb is not None and self.loop_res_scale is not None, (
                "Looped execution requires loop_core_steps > 1 in CinLMConfig"
            )

        x = self.tok_emb(input_ids)
        emb_out = x.detach() if capture_telemetry else None

        new_kv_caches: List[Optional[Tuple[torch.Tensor, torch.Tensor]]] = []
        new_engram_states: Dict[int, EngramState] = {}
        layer_telemetries: List[Dict[str, Any]] = []
        loop_residuals: List[torch.Tensor] = []
        exec_slot = 0

        def _run_block(
            layer_idx: int,
            hidden: torch.Tensor,
            *,
            skip_engram: bool,
            record_tel: bool,
        ) -> torch.Tensor:
            nonlocal exec_slot
            layer = self.layers[layer_idx]
            kv_in = cache.kv_caches[exec_slot] if cache is not None else None
            eng_in = None if skip_engram else (cache.engram_states.get(layer_idx) if cache is not None else None)
            exec_slot += 1

            if (
                self.gradient_checkpointing
                and self.training
                and not use_cache
                and not capture_telemetry
                and intervention is None
            ):
                def _ckpt_fn(h: torch.Tensor, _layer=layer, _skip=skip_engram) -> torch.Tensor:
                    out_h, _, _, _ = _layer(
                        h,
                        input_ids=input_ids,
                        rope_cos=self.rope_cos,
                        rope_sin=self.rope_sin,
                        start_pos=start_pos,
                        skip_engram=_skip,
                    )
                    return out_h

                out_h = torch.utils.checkpoint.checkpoint(_ckpt_fn, hidden, use_reentrant=False)
                kv_out, eng_out, layer_tel = None, None, None
            else:
                out_h, kv_out, eng_out, layer_tel = layer(
                    hidden,
                    input_ids=input_ids,
                    rope_cos=self.rope_cos,
                    rope_sin=self.rope_sin,
                    start_pos=start_pos,
                    kv_cache=kv_in,
                    engram_state=eng_in,
                    intervention=intervention,
                    capture_telemetry=record_tel,
                    skip_engram=skip_engram,
                )

            if use_cache:
                new_kv_caches.append(kv_out)
                if not skip_engram and eng_out is not None:
                    new_engram_states[layer_idx] = eng_out
            if record_tel and layer_tel is not None:
                layer_telemetries.append(layer_tel)
            return out_h

        if active_loops == 1:
            for idx in range(self.config.n_layers):
                x = _run_block(idx, x, skip_engram=False, record_tel=capture_telemetry)
        else:
            s_idx = self.config.loop_start_layer
            e_idx = self.config.loop_end_layer

            # 1. Prelude (runs once)
            for idx in range(0, s_idx):
                x = _run_block(idx, x, skip_engram=False, record_tel=capture_telemetry)

            # 2. Recursive Core (r=0 exact base pass; r>=1 gated residual refinement)
            for r in range(active_loops):
                if r == 0:
                    for idx in range(s_idx, e_idx):
                        x = _run_block(idx, x, skip_engram=False, record_tel=capture_telemetry)
                else:
                    assert self.loop_step_emb is not None and self.loop_res_scale is not None
                    x_base = x
                    step_emb = self.loop_step_emb.weight[r].to(dtype=x.dtype)
                    x_ref = x_base + step_emb
                    for idx in range(s_idx, e_idx):
                        x_ref = _run_block(idx, x_ref, skip_engram=True, record_tel=False)
                    gate = torch.tanh(self.loop_res_scale[r]).to(dtype=x.dtype)
                    x = x_base + gate * (x_ref - x_base)
                if capture_telemetry:
                    loop_residuals.append(x.detach())

            # 3. Coda (runs once)
            for idx in range(e_idx, self.config.n_layers):
                x = _run_block(idx, x, skip_engram=False, record_tel=capture_telemetry)

        x_norm = self.final_norm(x)
        logits = self.lm_head(x_norm)

        loss: Optional[torch.Tensor] = None
        ntp_loss: Optional[torch.Tensor] = None
        mtp_loss: Optional[torch.Tensor] = None
        if labels is not None:
            shift_logits = logits[:, :-1, :].contiguous()
            shift_labels = labels[:, 1:].contiguous()
            ntp_loss = F.cross_entropy(
                shift_logits.view(-1, self.config.vocab_size),
                shift_labels.view(-1),
                ignore_index=-100,
            )
            loss = ntp_loss

            if (
                self.mtp_projs is not None
                and self.mtp_norms is not None
                and self.mtp_emb_norms is not None
                and self.mtp_out_norms is not None
                and self.config.mtp_num_heads > 0
            ):
                mtp_terms: List[torch.Tensor] = []
                h_prev = x_norm
                for k_idx in range(self.config.mtp_num_heads):
                    offset = k_idx + 1
                    if seq_len <= offset + 1:
                        break
                    # Strictly causal: predict token at (t + offset + 1) from h_t and tok_{t + offset}
                    h_cur = self.mtp_norms[k_idx](h_prev[:, : -(offset + 1), :])
                    e_next = self.mtp_emb_norms[k_idx](self.tok_emb(input_ids[:, offset:-1]))
                    h_fused = self.mtp_out_norms[k_idx](self.mtp_projs[k_idx](torch.cat([h_cur, e_next], dim=-1)))
                    mtp_logits = self.lm_head(h_fused)
                    mtp_targets = labels[:, offset + 1 :].contiguous()
                    if (mtp_targets != -100).any():
                        mtp_terms.append(
                            F.cross_entropy(
                                mtp_logits.reshape(-1, self.config.vocab_size),
                                mtp_targets.reshape(-1),
                                ignore_index=-100,
                            )
                        )
                    h_prev = h_fused
                if mtp_terms:
                    mtp_loss = sum(mtp_terms) / len(mtp_terms)  # type: ignore[assignment]
                    loss = ntp_loss + self.config.mtp_loss_weight * mtp_loss  # type: ignore[operator]

        out_cache = (
            CinLMCache(
                kv_caches=new_kv_caches,
                engram_states=new_engram_states,
                seq_len=start_pos + seq_len,
            )
            if use_cache
            else None
        )

        result: Dict[str, Any] = {
            "logits": logits,
            "loss": loss,
            "ntp_loss": ntp_loss,
            "mtp_loss": mtp_loss,
            "cache": out_cache,
        }
        if capture_telemetry:
            result["telemetry"] = {
                "emb_out": emb_out,
                "final_residual": x.detach(),
                "layers": layer_telemetries,
                "loop_residuals": loop_residuals,
            }
        return result

    @torch.no_grad()
    def generate(
        self,
        input_ids: torch.Tensor,
        max_new_tokens: int = 64,
        temperature: float = 0.8,
        top_k: int = 40,
        top_p: float = 1.0,
        repetition_penalty: float = 1.0,
        eos_token_id: Optional[int] = None,
        num_loops: Optional[int] = None,
    ) -> torch.Tensor:
        """Autoregressive generation using exact hybrid KV + Engram cache."""
        self.eval()
        out = self.forward(input_ids, use_cache=True, num_loops=num_loops)
        cache = out["cache"]
        logits = out["logits"][:, -1, :]
        generated = [input_ids]
        seen_ids = input_ids.clone()

        for _ in range(max_new_tokens):
            step_logits = logits
            if repetition_penalty != 1.0:
                step_logits = step_logits.clone()
                for b in range(step_logits.size(0)):
                    uniq = torch.unique(seen_ids[b])
                    scores = step_logits[b, uniq]
                    step_logits[b, uniq] = torch.where(
                        scores > 0, scores / repetition_penalty, scores * repetition_penalty
                    )

            if temperature <= 0.0:
                next_tok = torch.argmax(step_logits, dim=-1, keepdim=True)
            else:
                scaled = step_logits / temperature
                if top_k > 0:
                    v, _ = torch.topk(scaled, min(top_k, scaled.size(-1)))
                    scaled = scaled.masked_fill(scaled < v[:, [-1]], float("-inf"))
                if 0.0 < top_p < 1.0:
                    sorted_logits, sorted_idx = torch.sort(scaled, descending=True, dim=-1)
                    cum_probs = torch.cumsum(F.softmax(sorted_logits, dim=-1), dim=-1)
                    remove = cum_probs > top_p
                    remove[..., 1:] = remove[..., :-1].clone()
                    remove[..., 0] = False
                    sorted_logits = sorted_logits.masked_fill(remove, float("-inf"))
                    scaled = torch.full_like(scaled, float("-inf")).scatter(-1, sorted_idx, sorted_logits)
                probs = F.softmax(scaled, dim=-1)
                next_tok = torch.multinomial(probs, num_samples=1)

            generated.append(next_tok)
            seen_ids = torch.cat([seen_ids, next_tok], dim=1)
            if eos_token_id is not None and (next_tok == eos_token_id).all():
                break
            if cache.seq_len >= self.config.max_seq_len:
                break

            out = self.forward(next_tok, cache=cache, use_cache=True, num_loops=num_loops)
            cache = out["cache"]
            logits = out["logits"][:, -1, :]

        return torch.cat(generated, dim=1)
